const response = await fetch("https://bedrock-runtime.us-east-1.amazonaws.com/model/amazon.titan-text-premier-v1:0/invoke", {
  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({
    inputText: "Hello!",
    textGenerationConfig: { maxTokenCount: 512 },
  }),
});
const data = await response.json();
console.log(data.results[0].outputText);
